//! Per-user details from `badge.toml`, generated by `build.rs`.
use crate::qr::Qr;

pub struct Contact {
    pub label: &'static str,
    pub qr: Qr,
}

/// A network the badge may join, in preference order. No password means an open network.
pub struct Wifi {
    pub ssid: &'static str,
    pub password: Option<&'static str>,
}

/// The WebSocket relay that `cargo badge --relay` also connects to (see `relay/`).
pub struct Relay {
    pub url: &'static str,
    pub token: &'static str,
}

include!(concat!(env!("OUT_DIR"), "/config.rs"));
